def find_cycles_of_length(n, length):
    """Find all cycles of given length"""
    cycles = []

    if length == 3:
        for i in range(n):
            for j in range(i+1, n):
                for k in range(j+1, n):
                    cycles.append([(i,j), (j,k), (i,k)])
    elif length == 4:
        for i in range(n):
            for j in range(i+1, n):
                for k in range(j+1, n):
                    for l in range(k+1, n):
                        # Check all 3 possible 4-cycles on these 4 vertices
                        cycles.append([(i,j), (j,k), (k,l), (i,l)])
                        cycles.append([(i,j), (j,l), (k,l), (i,k)])
                        cycles.append([(i,k), (j,k), (j,l), (i,l)])
    elif length == 5:
        # This gets expensive, let's be smarter
        pass
    elif length == 6:
        pass

    return cycles

# For a more efficient approach, let's enumerate cycles by BFS
def enumerate_cycles(n, max_len):
    """Enumerate all cycles of length 3 to max_len"""
    cycles = []

    # Build complete graph adjacency
    adj = {i: set(range(i+1, n)) | set(range(0, i)) for i in range(n)}

    for start in range(n):
        # BFS to find cycles
        # State: (current_vertex, path)
        stack = [(start, [start])]

        while stack:
            v, path = stack.pop()
            if len(path) > max_len:
                continue

            for neighbor in adj[v]:
                if neighbor == start and len(path) >= 3:
                    # Found a cycle
                    cycle_edges = []
                    for i in range(len(path)):
                        u1, u2 = path[i], path[(i+1) % len(path)]
                        cycle_edges.append((min(u1,u2), max(u1,u2)))
                    cycles.append(cycle_edges)
                elif neighbor not in path and len(path) < max_len:
                    stack.append((neighbor, path + [neighbor]))

    return cycles

